// Calculate tomorrow's date string (YYYY-MM-DD)
const tomorrow = new Date();
tomorrow.setDate(tomorrow.getDate() + 1);
const tomorrowStr = tomorrow.toISOString().split('T')[0];

// Mock tomorrow's confirmed operations (In production, fetched from Airtable/PostgreSQL)
const tomorrowOperations = [
  {
    service_id: "ITM-2026-001-D1",
    service_type: "Airport Transfer",
    service_time: "14:30",
    client_name: "Sarah Jenkins",
    pax_count: 2,
    flight_number: "AZ 1284 (FCO -> NAP)",
    pickup_point: "Naples International Airport (NAP) - Arrivals Gate",
    dropoff_point: "Grand Hotel Excelsior Vittoria, Sorrento",
    assigned_driver: "Antonio De Luca",
    driver_phone: "+39333444555",
    vehicle_plate: "Mercedes V-Class (FX 892 TR)",
    special_instructions: "VIP 25th anniversary guests. Provide chilled water and wet towels."
  },
  {
    service_id: "ITM-2026-002-D2",
    service_type: "Private Guided Tour",
    service_time: "09:30",
    client_name: "David Schmidt",
    pax_count: 4,
    flight_number: "N/A",
    pickup_point: "Hotel Lobby, Sorrento",
    dropoff_point: "Pompeii Archaeological Park",
    assigned_driver: "Marco Bianchi",
    driver_phone: "+39333555666",
    vehicle_plate: "Mercedes Sprinter (GG 441 AB)",
    assigned_guide: "Elena Ferrara",
    guide_phone: "+39333666777",
    special_instructions: "German-speaking guide Elena Ferrara requested."
  }
];

// Group into individual driver manifests
const driverManifests = {};
tomorrowOperations.forEach(op => {
  if (!driverManifests[op.driver_phone]) {
    driverManifests[op.driver_phone] = {
      driver_name: op.assigned_driver,
      driver_phone: op.driver_phone,
      vehicle_plate: op.vehicle_plate,
      date: tomorrowStr,
      assignments: []
    };
  }
  driverManifests[op.driver_phone].assignments.push(op);
});

const output = Object.values(driverManifests).map(m => {
  let msg = `📋 *DAILY DISPATCH MANIFEST - ${m.date}*\n`;
  msg += `Driver: *${m.driver_name}* | Vehicle: ${m.vehicle_plate}\n`;
  msg += `━━━━━━━━━━━━━━━━━━━━\n`;

  m.assignments.forEach((a, i) => {
    msg += `*Stop #${i + 1}: ${a.service_time} - ${a.service_type}*\n`;
    msg += `• Lead Guest: ${a.client_name} (${a.pax_count} Pax)\n`;
    if (a.flight_number !== 'N/A') msg += `• Flight: ${a.flight_number}\n`;
    msg += `• From: ${a.pickup_point}\n`;
    msg += `• To: ${a.dropoff_point}\n`;
    if (a.special_instructions) msg += `• Notes: _${a.special_instructions}_\n`;
    msg += `\n`;
  });

  msg += `📞 24/7 Operations Desk: +39 081 555 9999\nPlease reply *ACK* to confirm receipt.`;

  return {
    json: {
      driver_name: m.driver_name,
      driver_phone: m.driver_phone,
      date: m.date,
      manifest_text: msg
    }
  };
});

return output;
